/**
 * Escapes characters for XML safety
 */
function escapeXml(unsafe: string): string {
  return unsafe
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

function toWesternNumerals(str: string): string {
  const indicDigits = ["٠", "١", "٢", "٣", "٤", "٥", "٦", "٧", "٨", "٩"];
  return str.replace(/[٠-٩]/g, (char) => {
    const idx = indicDigits.indexOf(char);
    return idx !== -1 ? String(idx) : char;
  });
}

/**
 * Generates the official member ID card as a valid, standalone SVG string.
 */
export function generateMemberIdCardSvg(data: MemberIdCardData): string {
  const safeNameAr = escapeXml(data.fullNameAr || "عضو المؤسسة");
  const safeNameEn = escapeXml((data.fullNameEn || "").toUpperCase());
  const safeTitleAr = escapeXml(data.titleAr || "عضو الهيئة العامة");
  const safeTitleEn = escapeXml((data.titleEn || "General Member").toUpperCase());
  const safeMemNum = escapeXml(toWesternNumerals(data.membershipNumber || ""));
  const safeJoinDate = escapeXml(toWesternNumerals(data.joinDate || ""));
  const safeExpiryDate = escapeXml(toWesternNumerals(data.expiryDate || ""));

  // Dynamic font sizing for Arabic name scaled up by 30% (+30% from 8.5px = 11.05px)
  const nameArLen = safeNameAr.length;
  const nameArFontSize =
    nameArLen > 30 ? "8.1px" : nameArLen > 24 ? "9.1px" : nameArLen > 18 ? "10px" : "11px";
  const nameArSvg = `<text class="cls-4" x="89" y="62" text-anchor="end" font-size="${nameArFontSize}" font-weight="800"><tspan x="89" y="62">${safeNameAr}</tspan></text>`;

  // Dynamic font sizing for English name scaled up by 30% (+30% from 5.2px = 6.76px)
  const nameEnLen = safeNameEn.length;
  const nameEnFontSize =
    nameEnLen > 30 ? "5.2px" : nameEnLen > 24 ? "5.9px" : "6.8px";
  const nameEnSvg = safeNameEn
    ? `<text class="cls-6" x="89" y="72.5" text-anchor="end" font-size="${nameEnFontSize}" font-weight="600" letter-spacing="0.2"><tspan x="89" y="72.5">${safeNameEn}</tspan></text>`
    : "";

  // Department section
  const depSectionSvg = `<g>
        <text class="cls-5" transform="translate(75.36 104.88)"><tspan x="0" y="0">DEP.</tspan></text>
        <text class="cls-7" transform="translate(75.36 96.78)"><tspan x="0" y="0">القسم</tspan></text>
        <text x="70" y="96.78" fill="#000000ff" font-family="'ThmanyahSerifDisplay', 'Cairo', sans-serif" font-size="5.8" font-weight="700" text-anchor="end">
          ${safeTitleAr}
        </text>
        <text x="70" y="104.88" fill="#475569" font-family="'ThmanyahSans', 'Inter', sans-serif" font-size="4.2" font-weight="600" text-anchor="end" letter-spacing="0.2">
          ${safeTitleEn}
        </text>
      </g>`;

  // Photo frame
  const initial = safeNameAr.charAt(0);
  const photoFrameSvg = `
      <g id="member-photo-frame">
        <rect class="cls-1" x="95.51" y="50.44" width="46.02" height="61.35" rx="6.94" ry="6.94"/>
        <g clip-path="url(#member-photo-clip)">
          ${data.avatarPath ? `
            <image href="${data.avatarPath}" x="95.51" y="50.44" width="46.02" height="61.35" preserveAspectRatio="xMidYMid slice" />
          ` : `
            <rect x="95.51" y="50.44" width="46.02" height="61.35" fill="#fde9f1" />
            <circle cx="118.52" cy="76" r="15" fill="#e0f2fe" stroke="#38bdf8" stroke-width="0.8" />
            <text x="118.52" y="82.5" fill="#0284c7" font-family="'ThmanyahSerifDisplay', 'Cairo', sans-serif" font-size="18" font-weight="900" text-anchor="middle">
              ${initial}
            </text>
          `}
        </g>
        <rect x="95.51" y="50.44" width="46.02" height="61.35" rx="6.94" ry="6.94" fill="none" stroke="#231f20" stroke-width="0.5"/>
      </g>`;

  // Dynamic QR Code (without central logo for clean fast camera reading)
  const qrSectionSvg = `<g id="qr-code-section">
        <rect class="cls-8" x="11.55" y="167.65" width="56.61" height="57.78" rx="4.68" ry="4.68" stroke="#231f20" stroke-width="0.25"/>
        ${data.qrDataUrl ? `
          <image href="${data.qrDataUrl}" x="13.55" y="169.65" width="52.61" height="53.78" preserveAspectRatio="xMidYMid meet" />
        ` : `
          <rect x="13.55" y="169.65" width="52.61" height="53.78" fill="#f8fafc" rx="4" />
        `}
      </g>`;

  // Box values
  const boxValuesSvg = `
      <!-- Dynamic Values for the 3 Badges -->
      <text x="16" y="122.8" fill="#000000ff" font-family="'JetBrains Mono', 'Courier New', monospace" font-size="5.8" font-weight="800" letter-spacing="0.2">
        ${safeMemNum}
      </text>
      <text x="16" y="139.5" fill="#231f20" font-family="'ThmanyahSans', 'Cairo', sans-serif" font-size="5.2" font-weight="700">
        ${safeJoinDate}
      </text>
      <text x="16" y="156" fill="#231f20" font-family="'ThmanyahSans', 'Cairo', sans-serif" font-size="5.2" font-weight="700">
        ${safeExpiryDate}
      </text>`;

  let result = BASE_CARD_SVG_TEMPLATE
    .replace('<!-- __NAME_AR_PLACEHOLDER__ -->', nameArSvg)
    .replace('<!-- __NAME_EN_PLACEHOLDER__ -->', nameEnSvg)
    .replace('<!-- __DEP_SECTION_PLACEHOLDER__ -->', depSectionSvg)
    .replace('<!-- __PHOTO_FRAME_PLACEHOLDER__ -->', photoFrameSvg)
    .replace('<!-- __QR_SECTION_PLACEHOLDER__ -->', qrSectionSvg)
    .replace('<!-- __BOX_VALUES_PLACEHOLDER__ -->', boxValuesSvg);

  return result;
}
